// SSE counterpart of x86_64-union-abi.c.  A union is lowered to the IR type
// of its largest member, so bytes that are padding in that member are
// invisible to the IR-type walk that picks the SSE coercion type.  When a
// smaller member has a field in those bytes, the coercion has to cover the
// whole eightbyte (double), otherwise those bytes are dropped when the union
// is passed or returned in SSE registers.

union FloatFloatDouble {
  struct { float a; float b; } s;
  struct { float x; double y; } t;
};

void take_ffd(union FloatFloatDouble u);
// CHECK-LABEL: define dso_local void @call_take_ffd(
// CHECK-SAME: double [[U_COERCE0:%.*]], double [[U_COERCE1:%.*]]) #[[ATTR0:[0-9]+]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[U:%.*]] = alloca [[UNION_FLOATFLOATDOUBLE:%.*]], align 8
// CHECK-NEXT:    [[TMP0:%.*]] = getelementptr inbounds nuw { double, double }, ptr [[U]], i32 0, i32 0
// CHECK-NEXT:    store double [[U_COERCE0]], ptr [[TMP0]], align 8
// CHECK-NEXT:    [[TMP1:%.*]] = getelementptr inbounds nuw { double, double }, ptr [[U]], i32 0, i32 1
// CHECK-NEXT:    store double [[U_COERCE1]], ptr [[TMP1]], align 8
// CHECK-NEXT:    [[TMP2:%.*]] = getelementptr inbounds nuw { double, double }, ptr [[U]], i32 0, i32 0
// CHECK-NEXT:    [[TMP3:%.*]] = load double, ptr [[TMP2]], align 8
// CHECK-NEXT:    [[TMP4:%.*]] = getelementptr inbounds nuw { double, double }, ptr [[U]], i32 0, i32 1
// CHECK-NEXT:    [[TMP5:%.*]] = load double, ptr [[TMP4]], align 8
// CHECK-NEXT:    call void @take_ffd(double [[TMP3]], double [[TMP5]])
// CHECK-NEXT:    ret void
//
void call_take_ffd(union FloatFloatDouble u) { take_ffd(u); }

// The second float lives in the padding of the larger member, so both
// eightbytes have to travel whole.

union FloatFloatDouble ret_ffd(void);
// CHECK-LABEL: define dso_local void @call_ret_ffd(
// CHECK-SAME: ) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[COERCE:%.*]] = alloca [[UNION_FLOATFLOATDOUBLE:%.*]], align 8
// CHECK-NEXT:    [[CALL:%.*]] = call { double, double } @ret_ffd()
// CHECK-NEXT:    [[COERCE_DIVE:%.*]] = getelementptr inbounds nuw [[UNION_FLOATFLOATDOUBLE]], ptr [[COERCE]], i32 0, i32 0
// CHECK-NEXT:    [[TMP0:%.*]] = getelementptr inbounds nuw { double, double }, ptr [[COERCE_DIVE]], i32 0, i32 0
// CHECK-NEXT:    [[TMP1:%.*]] = extractvalue { double, double } [[CALL]], 0
// CHECK-NEXT:    store double [[TMP1]], ptr [[TMP0]], align 8
// CHECK-NEXT:    [[TMP2:%.*]] = getelementptr inbounds nuw { double, double }, ptr [[COERCE_DIVE]], i32 0, i32 1
// CHECK-NEXT:    [[TMP3:%.*]] = extractvalue { double, double } [[CALL]], 1
// CHECK-NEXT:    store double [[TMP3]], ptr [[TMP2]], align 8
// CHECK-NEXT:    ret void
//
void call_ret_ffd(void) { ret_ffd(); }


// The <2 x half> coercion would only cover the first half of the low
// eightbyte; the float member t.c forces the full eightbyte again.
union HalfHalfDouble {
  struct { _Float16 a; _Float16 b; double c; } s;
  struct { _Float16 a; _Float16 b; float c; } t;
};

void take_hhd(union HalfHalfDouble u);
// CHECK-LABEL: define dso_local void @call_take_hhd(
// CHECK-SAME: double [[U_COERCE0:%.*]], double [[U_COERCE1:%.*]]) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
