// CHECK-NEXT:    store double [[U_COERCE1]], ptr [[TMP1]], align 8
// CHECK-NEXT:    [[TMP2:%.*]] = getelementptr inbounds nuw { double, double }, ptr [[U]], i32 0, i32 0
// CHECK-NEXT:    [[TMP3:%.*]] = load double, ptr [[TMP2]], align 8
// CHECK-NEXT:    [[TMP4:%.*]] = getelementptr inbounds nuw { double, double }, ptr [[U]], i32 0, i32 1
// CHECK-NEXT:    [[TMP5:%.*]] = load double, ptr [[TMP4]], align 8
// CHECK-NEXT:    call void @take_hhd(double [[TMP3]], double [[TMP5]])
// CHECK-NEXT:    ret void
//
void call_take_hhd(union HalfHalfDouble u) { take_hhd(u); }


// Nothing covers the tail of an over-aligned union, so those bytes are
// padding and the coercion is the float alone rather than the full
// eightbyte.
union FloatOverAligned8 {
  float f;
} __attribute__((aligned(8)));

void take_foa8(union FloatOverAligned8 u);
// CHECK-LABEL: define dso_local void @call_take_foa8(
// CHECK-SAME: float [[U_COERCE:%.*]]) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[U:%.*]] = alloca [[UNION_FLOATOVERALIGNED8:%.*]], align 8
// CHECK-NEXT:    [[COERCE_DIVE:%.*]] = getelementptr inbounds nuw [[UNION_FLOATOVERALIGNED8]], ptr [[U]], i32 0, i32 0
// CHECK-NEXT:    store float [[U_COERCE]], ptr [[COERCE_DIVE]], align 8
// CHECK-NEXT:    [[COERCE_DIVE1:%.*]] = getelementptr inbounds nuw [[UNION_FLOATOVERALIGNED8]], ptr [[U]], i32 0, i32 0
// CHECK-NEXT:    [[TMP0:%.*]] = load float, ptr [[COERCE_DIVE1]], align 8
// CHECK-NEXT:    call void @take_foa8(float [[TMP0]])
// CHECK-NEXT:    ret void
//
void call_take_foa8(union FloatOverAligned8 u) { take_foa8(u); }


// When every byte of the eightbyte is covered by fields of the largest
// member, the natural <2 x float> coercion keeps working.
union TwoFloats {
  struct { float a; float b; } s;
  float f;
};

void take_twof(union TwoFloats u);
// CHECK-LABEL: define dso_local void @call_take_twof(
